import os
import boto3

def extract_key_values(payload, config=None):
    config = config or {}
    client = boto3.client(
        'textract',
        aws_access_key_id=config.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=config.get('AWS_SECRET_ACCESS_KEY'),
        region_name=config.get('AWS_REGION', 'us-east-1')
    )
    response = client.analyze_document(Document={'Bytes': payload}, FeatureTypes=['FORMS'])
    blocks = {b['Id']: b for b in response['Blocks']}
    _out = {}
    for b in response['Blocks']:
        if b['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in b['EntityTypes']:
            k_ids = next((r['Ids'] for r in b.get('Relationships', []) if r['Type'] == 'CHILD'), [])
            key = ' '.join([blocks[i]['Text'] for i in k_ids])
            v_ids = next((r['Ids'] for r in b.get('Relationships', []) if r['Type'] == 'VALUE'), [])
            if v_ids:
                v_block = blocks[v_ids[0]]
                w_ids = next((r['Ids'] for r in v_block.get('Relationships', []) if r['Type'] == 'WORD'), [])
                _out[key] = ' '.join([blocks[i]['Text'] for i in w_ids])
    result = _out
    return result
